import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 7;
    static final int MOD = 1000000007;
    static final int E100 = 570000004;
    static int n;
    static int[][] g = new int[MAXN][MAXN];
    static long[][] nxt = new long[1 << MAXN][1 << MAXN];
    static int[] bitcnt = new int[1 << MAXN];
    static List<Integer>[] S = new ArrayList[MAXN + 1];
    static int[] id = new int[1 << MAXN];
    static Map<Long, Integer>[] dp = new HashMap[MAXN];

    static {
        for (int i = 0; i <= MAXN; i++) {
            S[i] = new ArrayList<>();
        }
        for (int i = 0; i < MAXN; i++) {
            dp[i] = new HashMap<>();
        }
    }

    static int solve(int i, long msk) {
        if (msk == 0) return 0;
        if (i == n) return 1;
        if (dp[i].containsKey(msk)) return dp[i].get(msk);
        long ret = 0;
        for (int s = 0; s < (1 << n); s++) {
            long p = 1;
            for (int j = 0; j < n; j++) {
                if ((s & (1 << j)) != 0) {
                    p = (p * g[i][j]) % MOD;
                } else {
                    p = (p * (MOD + 1 - g[i][j])) % MOD;
                }
            }
            long nmsk = 0;
            for (int j = 0; j < 35; j++) {
                if (((msk >> j) & 1) != 0) {
                    nmsk |= nxt[s][S[i][j]];
                }
            }
            ret = (ret + p * solve(i + 1, nmsk)) % MOD;
        }
        dp[i].put(msk, (int) ret);
        return (int) ret;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < n; j++) {
                g[i][j] = Integer.parseInt(parts[j]) * E100 % MOD;
            }
        }
        for (int i = 1; i < (1 << n); i++) {
            bitcnt[i] = bitcnt[i ^ (i & -i)] + 1;
        }
        for (int i = 0; i < (1 << n); i++) {
            int c = bitcnt[i];
            id[i] = S[c].size();
            S[c].add(i);
        }
        for (int i = 1; i < (1 << n); i++) {
            for (int j = 0; j < (1 << n); j++) {
                for (int k = 0; k < n; k++) {
                    if (((i & (1 << k)) != 0) && ((j & (1 << k)) == 0)) {
                        nxt[i][j] |= 1L << id[j | (1 << k)];
                    }
                }
            }
        }
        int ans = solve(0, 1);
        ans = ((ans % MOD) + MOD) % MOD;
        System.out.println(ans);
    }
}
